{"file_text": "@using sv_2ca55cf789bf485f9e44a3d08d4ab640.Services
@inject IJSRuntime JS

<div class="message-area">
    <div class="area-header">
        <h2 class="channel-title"># @ChannelName</h2>
        @if (!string.IsNullOrEmpty(ChannelDescription))
        {
            <span class="channel-description">@ChannelDescription</span>
        }
    </div>

    <div class="message-list" @ref="messageListRef" @onscroll="HandleScroll">
        @if (IsLoadingMore)
        {
            <div class="loading-indicator">Loading older messages…</div>
        }
        @foreach (var msg in Messages)
        {
            <MessageItem Message="msg"
                         ThreadReplyCount="GetThreadReplyCount(msg.Id)"
                         OnOpenThread="() => OnOpenThread.InvokeAsync(msg.Id)"
                         OnReaction="(emoji) => OnReaction.InvokeAsync((msg.Id, emoji))" />
        }
    </div>

    <MessageInput Placeholder="@($"Message #{ChannelName}")"
                  OnSend="OnSendMessage" />
</div>

@code {
    [Parameter] public string ChannelName { get; set; } = "";
    [Parameter] public string ChannelDescription { get; set; } = "";
    [Parameter, EditorRequired] public List<Message> Messages { get; set; } = [];
    [Parameter] public Dictionary<int, int> ThreadReplyCounts { get; set; } = [];
    [Parameter] public bool IsLoadingMore { get; set; }
    [Parameter] public EventCallback<int> OnOpenThread { get; set; }
    [Parameter] public EventCallback<(int MessageId, string Emoji)> OnReaction { get; set; }
    [Parameter] public EventCallback<string> OnSendMessage { get; set; }
    [Parameter] public EventCallback OnLoadMore { get; set; }

    private ElementReference messageListRef;
    private bool hasScrolledInitially;

    protected override async Task OnAfterRenderAsync(bool firstRender)
    {
        if (!hasScrolledInitially && Messages.Count > 0)
        {
            hasScrolledInitially = true;
            await JS.InvokeVoidAsync("eval",
                "document.querySelector('[data-scroll-bottom]')?.scrollTo(0, 999999)");
        }
    }

    private async Task HandleScroll()
    {
        var scrollTop = await JS.InvokeAsync<double>("eval",
            "document.querySelector('[data-scroll-bottom]')?.scrollTop ?? 1");

        if (scrollTop < 50 && !IsLoadingMore)
        {
            await OnLoadMore.InvokeAsync();
        }
    }

    private int GetThreadReplyCount(int messageId) =>
        ThreadReplyCounts.GetValueOrDefault(messageId);
}
