@using sv_2ca55cf789bf485f9e44a3d08d4ab640.Services

<aside class="thread-panel">
    <div class="thread-header">
        <span class="thread-title">Thread</span>
        <button class="close-btn" @onclick="OnClose">✕</button>
    </div>

    @if (RootMessage is not null)
    {
        <div class="root-message-quote">
            <MessageItem Message="RootMessage" ShowActions="false" />
        </div>

        <div class="thread-divider">
            <span>@Replies.Count @(Replies.Count == 1 ? "reply" : "replies")</span>
        </div>

        <div class="thread-messages">
            @foreach (var reply in Replies)
            {
                <MessageItem Message="reply" ShowActions="false" />
            }
        </div>

        <MessageInput Placeholder="Reply to thread…"
                      ButtonLabel="Reply"
                      OnSend="OnReplySend" />
    }
</aside>

@code {
    [Parameter, EditorRequired] public Message? RootMessage { get; set; }
    [Parameter] public List<Message> Replies { get; set; } = [];
    [Parameter] public EventCallback OnClose { get; set; }
    [Parameter] public EventCallback<string> OnReplySend { get; set; }
}

.thread-panel {
    width: 100%;
    height: 100%;
    background: #36393f;
    display: flex;
    flex-direction: column;
    border-left: 1px solid #222;
    overflow: hidden;
}

.thread-header {
    display: flex;
    align-items: center;
    justify-content: space-between;
    padding: 12px 16px;
    border-bottom: 1px solid #3a3d42;
    background: #2f3136;
}

.thread-title {
    font-weight: 700;
    font-size: 1rem;
    color: #fff;
}

.close-btn {
    background: none;
    border: none;
    color: #b9bbbe;
    font-size: 1.1rem;
    cursor: pointer;
    padding: 4px 8px;
    border-radius: 4px;
    transition: background-color 0.15s, color 0.15s;
}

.close-btn:hover {
    background-color: rgba(255, 255, 255, 0.1);
    color: #fff;
}

.root-message-quote {
    padding: 8px 0;
    border-bottom: 1px solid #3a3d42;
    background: rgba(0, 0, 0, 0.1);
}

.thread-divider {
    display: flex;
    align-items: center;
    padding: 6px 16px;
    font-size: 0.75rem;
    color: #72767d;
    font-weight: 600;
}

.thread-messages {
    flex: 1;
    overflow-y: auto;
    padding: 4px 0;
}

