arguments.file_text:
@page "/chat"
@rendermode InteractiveServer
@using sv_2ca55cf789bf485f9e44a3d08d4ab640.Services
@using sv_2ca55cf789bf485f9e44a3d08d4ab640.Components.Chat
@inject IChatService ChatService

<PageTitle>Chat</PageTitle>

<div class="chat-layout">
    <div class="sidebar-column">
        <ChannelSidebar Channels="channels"
                        ActiveChannelId="selectedChannelId"
                        OnChannelSelected="SelectChannel" />
    </div>

    <div class="main-column @(isThreadOpen ? "" : "expanded")">
        @if (selectedChannel is not null)
        {
            <MessageArea ChannelName="@selectedChannel.Name"
                         ChannelDescription="@selectedChannel.Description"
                         Messages="messages"
                         ThreadReplyCounts="threadReplyCounts"
                         IsLoadingMore="isLoadingMore"
                         OnOpenThread="OpenThread"
                         OnReaction="HandleReaction"
                         OnSendMessage="SendMessage"
                         OnLoadMore="LoadMoreMessages" />
        }
        else
        {
            <div class="empty-state">
                <p>Select a channel to start chatting</p>
            </div>
        }
    </div>

    @if (isThreadOpen && threadRootMessage is not null)
    {
        <div class="thread-column">
            <ThreadPanel RootMessage="threadRootMessage"
                         Replies="threadReplies"
                         OnClose="CloseThread"
                         OnReplySend="SendThreadReply" />
        </div>
    }
</div>

@code {
    private List<Channel> channels = [];
    private List<Message> messages = [];
    private Dictionary<int, int> threadReplyCounts = [];
    private Channel? selectedChannel;
    private int? selectedChannelId;

    private bool isThreadOpen;
    private Message? threadRootMessage;
    private List<Message> threadReplies = [];

    private bool isLoadingMore;
    private const int PageSize = 30;

    protected override async Task OnInitializedAsync()
    {
        channels = await ChatService.GetChannelsAsync();

        if (channels.Count > 0)
        {
            await SelectChannel(channels[0].Id);
        }
    }

    private async Task SelectChannel(int channelId)
    {
        if (selectedChannelId == channelId) return;

        selectedChannelId = channelId;
        selectedChannel = channels.FirstOrDefault(c => c.Id == channelId);
        messages = [];
        threadReplyCounts = [];
        CloseThread();

        messages = await ChatService.GetMessagesAsync(channelId, 0, PageSize);
        await LoadThreadCounts();

        await ChatService.MarkChannelReadAsync(channelId);
        // Refresh the channel list to update unread badges
        channels = await ChatService.GetChannelsAsync();
    }

    private async Task LoadMoreMessages()
    {
        if (isLoadingMore || selectedChannelId is null) return;

        isLoadingMore = true;
        StateHasChanged();

        var older = await ChatService.GetMessagesAsync(selectedChannelId.Value, messages.Count, PageSize);

        if (older.Count > 0)
        {
            messages.InsertRange(0, older);
            await LoadThreadCounts();
        }

        isLoadingMore = false;
    }

    private async Task SendMessage(string content)
    {
        if (selectedChannelId is null) return;

        var message = await ChatService.SendMessageAsync(selectedChannelId.Value, content, null);
        messages.Add(message);
    }

    private async Task OpenThread(int messageId)
    {
        threadRootMessage = messages.FirstOrDefault(m => m.Id == messageId);
        if (threadRootMessage is null) return;

        var allThread = await ChatService.GetThreadAsync(messageId);
        threadReplies = allThread.Where(m => m.Id != messageId).ToList();
        isThreadOpen = true;
    }

    private void CloseThread()
    {
        isThreadOpen = false;
        threadRootMessage = null;
        threadReplies = [];
    }

    private async Task SendThreadReply(string content)
    {
        if (selectedChannelId is null || threadRootMessage is null) return;

        var reply = await ChatService.SendMessageAsync(
            selectedChannelId.Value, content, threadRootMessage.Id);

        threadReplies.Add(reply);

        // Update thread count
        threadReplyCounts[threadRootMessage.Id] =
            threadReplyCounts.GetValueOrDefault(threadRootMessage.Id) + 1;
    }

    private async Task HandleReaction((int MessageId, string Emoji) args)
    {
        await ChatService.AddReactionAsync(args.MessageId, args.Emoji);

        // Refresh the affected message to show updated reactions
        if (selectedChannelId is not null)
        {
            messages = await ChatService.GetMessagesAsync(
                selectedChannelId.Value, 0, messages.Count);
        }
    }

    private async Task LoadThreadCounts()
    {
        // Build thread counts from messages that have replies pointing to them
        foreach (var msg in messages.Where(m => m.ReplyToId is null))
        {
            var thread = await ChatService.GetThreadAsync(msg.Id);
            var replyCount = thread.Count(t => t.Id != msg.Id);
            if (replyCount > 0)
            {
                threadReplyCounts[msg.Id] = replyCount;
            }
        }
    }
}

.chat-layout {
    display: flex;
    height: 100vh;
    width: 100%;
    background: #36393f;
    color: #dcddde;
    font-family: 'Segoe UI', Tahoma, Geneva, Verdana, sans-serif;
    overflow: hidden;
}

.sidebar-column {
    width: 20%;
    min-width: 200px;
    max-width: 280px;
    flex-shrink: 0;
}

.main-column {
    flex: 1;
    min-width: 0;
    display: flex;
    flex-direction: column;
}

.main-column.expanded {
    flex: 1;
}

.thread-column {
    width: 25%;
    min-width: 280px;
    max-width: 420px;
    flex-shrink: 0;
}

.empty-state {
    flex: 1;
    display: flex;
    align-items: center;
    justify-content: center;
    color: #72767d;
    font-size: 1.1rem;
}

