toolArgs.file_text:
.chat-layout {
    display: flex;
    height: 100vh;
    width: 100%;
    background: #36393f;
    color: #dcddde;
    font-family: 'Segoe UI', Tahoma, Geneva, Verdana, sans-serif;
    overflow: hidden;
}

.sidebar-column {
    width: 20%;
    min-width: 200px;
    max-width: 280px;
    flex-shrink: 0;
}

.main-column {
    flex: 1;
    min-width: 0;
    display: flex;
    flex-direction: column;
}

.main-column.expanded {
    flex: 1;
}

.thread-column {
    width: 25%;
    min-width: 280px;
    max-width: 420px;
    flex-shrink: 0;
}

.empty-state {
    flex: 1;
    display: flex;
    align-items: center;
    justify-content: center;
    color: #72767d;
    font-size: 1.1rem;
}

